623	\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
624		\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
625		\lean{MIPStarRE.QPBT.primeTauObservable, MIPStarRE.QPBT.primePauliFourier}
626		\lean{MIPStarRE.QPBT.primePauliVec, MIPStarRE.QPBT.primePauliProj}
627		\lean{MIPStarRE.QPBT.primePauliVec_orthonormal}
628		\lean{MIPStarRE.QPBT.primeTauObservable_mulVec_primePauliVec}
629		\lean{MIPStarRE.QPBT.primePauliProj_isProj, MIPStarRE.QPBT.sum_primePauliProj_eq_one}
630		\leanok
631		\uses{def:subfield-trace, def:lin-reg}
632		Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
633		observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
634		\begin{equation}\label{eq:pauli-fp}
635			\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
636			\qquad \text{and} \qquad
637			\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
638		\end{equation}
639		for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
640		\emph{generalized Pauli observables over $\F_q$} are the unitaries on
641		$\C^{\F_q}$
642		\[
643			\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
644			\qquad \text{and} \qquad
645			\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
646		\]
647		for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
648		(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
649		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
650		signs. All the $\tau^X$ operators commute with one another, as do all the
651		$\tau^Z$ operators. Their common eigenbases consist of the vectors
652		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
653		\[
654			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
655			\omega^{-\tr(ej)} \ket{j}\;, \qquad
656			\ket{e_Z} = \ket{e}\;;
657		\]
658		the Fourier transform
659		\begin{equation}\label{eq:fourier-f}
660			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
661			\omega^{-\tr(ab)} \ket{a}\bra{b}
662		\end{equation}
663		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
664		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
665		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
666		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
667		\[
668			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
669			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
670		\]
671		for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
672		The distinction between the general prime-characteristic definitions and
673		the characteristic-two specializations used by the Pauli basis test is
674		documented in \cite{gap:qpbt_characteristic-two-pauli-scope}.
675	\end{definition}
