728	\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
729		\lean{MIPStarRE.QPBT.ffChar_dotProduct_submodule_expect_eq_zero}
730		\leanok
731		\uses{def:dot-product-orthogonal, def:subfield-trace}
732		Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
733		$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
734		$v \notin V^\perp$,
735		\[
736			\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
737		\]
738		where the expectation is over a uniformly random vector $\bu$ in $V$.
739	\end{lemma}
740	\begin{proof}
741		\leanok
742		This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
743		the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
744		on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
745		shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
746		for the expectation, translation invariance of the uniform distribution on
747		$V$ gives
748		$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
749		= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
750		forces $C = 0$.
751	\end{proof}
