753	\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
754		\lean{MIPStarRE.QPBT.primeTauObservable_eq_sum_primePauliProj}
755		\lean{MIPStarRE.QPBT.primePauliProj_eq_avg_primeTauObservable}
756		\leanok
757		\uses{def:generalized-pauli, def:subfield-trace}
758		For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
759		% Paper equation label kept on the display it names.
760		\begin{equation}\label{eq:pauli-obs-proj}
761			\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
762		\end{equation}
763		and conversely
764		\begin{equation}\label{eq:pauli-inversion-0}
765			\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
766			= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
767			\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
768			= \tau^W_b\;.
769		\end{equation}
770		The source scope and the binary specialization of these identities are
771		recorded in \cite{gap:qpbt_characteristic-two-pauli-scope}.
772	\end{lemma}
773	\begin{proof}
774		\leanok
775		\uses{def:generalized-pauli, lem:cancellation}
776		Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
777		$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
778		definition, and for $W = X$ it follows from the single-qudit computation
779		$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
780		Expanding $\tau^W(a)$ in the orthonormal eigenbasis
781		$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
782		substitute the first display and exchange the order of summation; by
783		Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
784		$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
785		it equals $1$.
786	\end{proof}
